    fun create(
        pathData: String,
        fillColor: Color = Color.web("#d0d0d0"),
        size: Double = 16.0
    ): StackPane {
        val svg = SVGPath().apply {
            content = pathData
            fill = fillColor
        }
        val bounds = svg.boundsInLocal
        val maxDim = maxOf(bounds.width, bounds.height).coerceAtLeast(1.0)
        val scale = size / maxDim
        svg.scaleX = scale
        svg.scaleY = scale

        return StackPane(svg).apply {
            minWidth = size
            minHeight = size
            prefWidth = size
            prefHeight = size
            maxWidth = size
            maxHeight = size
            alignment = Pos.CENTER
        }
    }
